        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90030013-0000-4000-8000-000000000001', 'The term ''Universal Adult Franchise'' implies that:', '{"A":"Only property owners can vote","B":"Every adult citizen of 18 years or above has one vote with equal value","C":"Only educated men can vote","D":"Only taxpayers can contest"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Electoral Politics', 1, NULL, NULL, NULL, 'Universal adult franchise grants every citizen who is at least 18 years old the constitutional right to cast one vote, where each vote carries equal weight.', 'MEDIUM', true),
        ('90030013-0000-4000-8000-000000000002', 'Assertion (A): The Himalayas act as an effective climatic divide for the Indian subcontinent.
